'use strict';
const SALE_TABLES=['Parcelinha','Adesão de 1%','Adesão de 2%'];
let saleEditing=null;
function saleShares(s){if(s.allocations)return s.allocations.map(a=>[a.person,a.amount]);return s.originator===s.closer?[[s.originator,s.commission]]:[[s.originator,Math.floor(s.commission/2)],[s.closer,s.commission-Math.floor(s.commission/2)]];}
function validateSales(s){const ids=new Set();for(const x of s.saleEntries||[]){if(!x||typeof x.id!=='string'||ids.has(x.id)||typeof x.client!=='string'||!x.client.trim()||!validDate(x.date)||![0,1,2].includes(x.table)||![x.amount,x.commission].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=100000000000)||!s.people.some(p=>p.id===x.originator)||!s.people.some(p=>p.id===x.closer)||typeof x.voided!=='boolean')throw Error('Venda inválida');if(x.allocations&&(!Array.isArray(x.allocations)||x.allocations.length!==(x.originator===x.closer?1:2)||x.allocations.some((a,i)=>a.person!==[x.originator,x.closer][i]||!Number.isSafeInteger(a.amount)||a.amount<0||!Number.isFinite(a.rate)||a.rate<0||a.rate>100)||x.allocations.reduce((n,a)=>n+a.amount,0)!==x.commission))throw Error('Divisão inválida');ids.add(x.id);}if(s.saleEntries!==undefined&&!Array.isArray(s.saleEntries))throw Error('Vendas inválidas');for(const r of Object.values(s.records)){const b=r.salesBase;if(b&&(!Array.isArray(b.sales)||b.sales.length!==3||![b.commission,...b.sales].every(n=>Number.isFinite(n)&&n>=0)||typeof b.excluded!=='boolean'))throw Error('Histórico de vendas inválido');}}
function salesRecord(key){return state.records[key]??(state.records[key]={fare:0,rides:2,days:[],paid:{},sales:[0,0,0],commission:0,commissionPaid:false});}
function syncSales(){state.saleEntries??=[];for(const s of state.saleEntries){for(const id of new Set([s.originator,s.closer])){const r=salesRecord(s.date.slice(0,7)+':'+id);r.salesBase??={sales:[...r.sales],commission:r.commission,excluded:false};}}for(const r of Object.values(state.records)){if(r.salesBase){r.sales=r.salesBase.excluded?[0,0,0]:[...r.salesBase.sales];r.commission=r.salesBase.excluded?0:r.salesBase.commission;}}for(const s of state.saleEntries.filter(s=>!s.voided)){for(const [id,amount] of saleShares(s)){const r=salesRecord(s.date.slice(0,7)+':'+id);r.commission=(cents(r.commission)+amount)/100;r.sales[s.table]=(cents(r.sales[s.table])+s.amount)/100;}}}
function saleLocked(...entries){return entries.filter(Boolean).some(s=>[s.originator,s.closer].some(id=>state.records[s.date.slice(0,7)+':'+id]?.settlement));}
function putSale(entry){const old=(state.saleEntries||[]).find(s=>s.id===entry.id);if(saleLocked(old,entry))return false;if(old)Object.assign(old,entry);else (state.saleEntries??=[]).push({...entry});syncSales();return true;}
function salePerson(id){return state.people.find(p=>p.id===id)?.name||id;}
function monthlySales(){return (state.saleEntries||[]).filter(s=>s.date.startsWith($('#month').value));}
function salesRows(entries,person=null){return entries.length?`<div class="sale-table-wrap"><table class="sale-table"><thead><tr><th>Data / cliente</th><th>Tabela / venda</th><th>Quem trouxe</th><th>Quem fechou</th><th>${person?'Sua comissão':'Comissão total'}</th><th>Ações</th></tr></thead><tbody>${entries.map(s=>`<tr class="${s.voided?'voided':''}"><td>${esc(s.date.split('-').reverse().join('/'))}<strong>${esc(s.client)}</strong>${s.voided?'<small>Cancelada</small>':''}</td><td>${SALE_TABLES[s.table]}<strong>${money(s.amount/100)}</strong></td><td>${esc(salePerson(s.originator))}</td><td>${esc(salePerson(s.closer))}</td><td><strong>${money((person?saleShares(s).find(([id])=>id===person)?.[1]:s.commission)/100)}</strong><small>${s.originator===s.closer?'Venda completa':'Comissão dividida'}</small>${allocationDetail(s,person)}</td><td>${!s.voided?`<button data-edit-sale="${esc(s.id)}">Editar</button>`:''}<button data-void-sale="${esc(s.id)}">${s.voided?'Restaurar':'Cancelar'}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Nenhuma venda registrada neste mês.</p>';}
function renderSales(){const entries=monthlySales(),active=entries.filter(s=>!s.voided);$('#stats').innerHTML=[['Vendas do mês',active.reduce((n,s)=>n+s.amount,0)/100],...SALE_TABLES.map((t,i)=>[t,active.filter(s=>s.table===i).reduce((n,s)=>n+s.amount,0)/100])].map(([t,v])=>`<div class="stat"><span class="stat-label">${t}</span><strong>${money(v)}</strong><small>Volume vendido · cada venda contada uma vez</small></div>`).join('');$('#sales-section').innerHTML=`<div class="section-head"><div><span class="eyebrow">VENDAS DO MÊS</span><h2>Vendas e comissões</h2></div><button class="primary" data-add-sale>＋ Adicionar venda</button></div>${salesRows(entries)}`;}
function personSalesView(){const r=record(),b=r.salesBase||{sales:r.sales,commission:r.commission,excluded:false},hasLegacy=b.commission>0||b.sales.some(n=>n>0);return `<div class="section-head"><h3>Vendas e comissão do mês</h3><button data-main-view="sales">Abrir vendas do mês</button></div><p class="hint">As comissões vêm da lista geral de vendas. O valor da venda abaixo é integral; somente a comissão é dividida entre os participantes.</p>${salesRows(monthlySales().filter(s=>s.originator===selected||s.closer===selected),selected)}${hasLegacy?`<div class="balance-summary"><div>Totais anteriores ${b.excluded?'(fora do cálculo)':'incluídos no cálculo'}<strong>Comissão: ${money(b.commission)}</strong><small>Vendas: ${money(b.sales.reduce((a,n)=>a+n,0))}</small><p class="hint">Valores manuais antigos preservados. Ao cadastrar essas mesmas vendas na lista geral, retire os totais anteriores para não contar duas vezes.</p><button data-toggle-sales-base>${b.excluded?'Reincluir totais anteriores':'Retirar totais anteriores'}</button></div></div>`:''}${commissionPanel()}<p class="hint">Vales são descontados da comissão. Vale-transporte continua separado.</p>`;}
function openSale(id=null){saleEditing=id;const s=state.saleEntries.find(s=>s.id===id),f=$('#sale-form');f.reset();$('#sale-title').textContent=s?'Editar venda':'Adicionar venda';const opts='<option value="">Selecione uma pessoa</option>'+state.people.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.role||'PJ')}</option>`).join('');f.elements.originator.innerHTML=opts;f.elements.closer.innerHTML=opts;for(const k of ['client','date','table','originator','closer'])f.elements[k].value=s?s[k]:(k==='date'?$('#month').value+'-01':k==='table'?'0':'');f.elements.amount.value=s?formatCredit(s.amount):'';refreshSaleRates();if(s?.allocations){const first=s.allocations[0],same=s.originator===s.closer;f.elements.originRate.value=first.originRate??(same?first.rate/2:first.rate);f.elements.closerRate.value=first.closerRate??(same?first.rate/2:s.allocations.at(-1).rate);previewSale();}$('#sale-dialog').showModal();}
document.querySelector('#close-sale').onclick=()=>$('#sale-dialog').close();
document.querySelector('#sale-form').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const credit=parseCredit(f.elements.amount.value);if(!Number.isSafeInteger(credit)||credit<=0||credit>100000000000){toast('Informe um crédito válido, maior que zero e até R$ 1 bilhão.');return;}const entry={id:saleEditing||crypto.randomUUID(),client:f.elements.client.value.trim(),date:f.elements.date.value,table:Number(f.elements.table.value),originator:f.elements.originator.value,closer:f.elements.closer.value,amount:parseCredit(f.elements.amount.value),...calculateSale(parseCredit(f.elements.amount.value),Number(f.elements.table.value),f.elements.originator.value,f.elements.closer.value,Number(f.elements.originRate.value),Number(f.elements.closerRate.value)),voided:false};try{validateSales({...state,saleEntries:[entry]});}catch{toast('Confira os dados da venda.');return;}if(!putSale(entry)){toast('Reabra a comissão dos participantes antes de alterar esta venda.');return;}$('#month').value=entry.date.slice(0,7);save();render();$('#sale-dialog').close();toast('Venda salva e comissões atualizadas');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-add-sale'))openSale();if(b.dataset.editSale)openSale(b.dataset.editSale);if(b.dataset.voidSale){const s=state.saleEntries.find(s=>s.id===b.dataset.voidSale);if(!putSale({...s,voided:!s.voided})){toast('Reabra a comissão dos participantes antes de alterar esta venda.');return;}save();render();}if(b.hasAttribute('data-toggle-sales-base')){const r=record();if(r.settlement){toast('Reabra a comissão antes de alterar os totais anteriores.');return;}r.salesBase??={sales:[...r.sales],commission:r.commission,excluded:false};r.salesBase.excluded=!r.salesBase.excluded;syncSales();save();render();}});

function rateFor(person,table){if(table===0)return 0.8/12;const role=state.people.find(p=>p.id===person)?.commissionRole;return role==='PJ sem garantia'?(table===1?0.8:1):null;}
function calculateSale(amount,table,originator,closer,originRate,closerRate){if(table===0)originRate=closerRate=0.8/12;const same=originator===closer;if(same){const rate=originRate+closerRate,amountDue=Math.round(amount*rate/100);return {allocations:[{person:originator,rate,originRate,closerRate,amount:amountDue}],commission:amountDue};}const allocations=[{person:originator,rate:originRate,amount:Math.round(amount*originRate/100)},{person:closer,rate:closerRate,amount:Math.round(amount*closerRate/100)}];return {allocations,commission:allocations.reduce((n,a)=>n+a.amount,0)};}
function allocationDetail(s,person=null){return `<div class="sale-allocations">${saleShares(s).filter(([id])=>!person||id===person).map(([id,amount])=>{const a=s.allocations?.find(a=>a.person===id);return `<div><strong>${esc(salePerson(id))} · ${money(amount/100)}</strong><small>${s.originator===s.closer?'Trouxe e fechou':id===s.originator?'Trouxe o cliente':'Atendeu e fechou'}${a?' · '+(s.amount!==undefined?money(s.amount/100)+' × ':'')+(s.table===0?(s.originator===s.closer?'(0,8% ÷ 12) × 2':'0,8% ÷ 12'):(a.rate).toLocaleString('pt-BR',{maximumFractionDigits:6})+'% do crédito'):''}</small></div>`;}).join('')}</div>`;}
function refreshSaleRates(){const f=$('#sale-form'),table=Number(f.elements.table.value),same=f.elements.originator.value===f.elements.closer.value;for(const [field,person] of [['originRate',f.elements.originator.value],['closerRate',f.elements.closer.value]]){const r=rateFor(person,table);f.elements[field].value=r??'';f.elements[field].readOnly=r!==null;f.elements[field].required=true;}f.elements.closerRate.disabled=false;if(same&&f.elements.closerRate.value==='')f.elements.closerRate.value=f.elements.originRate.value;$('#sale-rate-note').textContent=table===0?'Parcelinha: cada participação recebe 0,066666…% do crédito na primeira parcela.':'A taxa informada é aplicada integralmente para quem trouxe e para quem fechou. Se for a mesma pessoa, as duas taxas são somadas.';previewSale();}
function previewSale(){const f=$('#sale-form'),o=f.elements.originator.value,c=f.elements.closer.value;const missing=!o||!c||!f.elements.amount.value||f.elements.originRate.value===''||f.elements.closerRate.value==='';$('#sale-preview').innerHTML=missing?'<p class="hint">Preencha o crédito, os participantes e as taxas para visualizar a divisão.</p>':allocationDetail({originator:o,closer:c,table:Number(f.elements.table.value),amount:parseCredit(f.elements.amount.value),...calculateSale(parseCredit(f.elements.amount.value),Number(f.elements.table.value),o,c,Number(f.elements.originRate.value),Number(f.elements.closerRate.value))});}
document.querySelector('#sale-form').addEventListener('change',e=>{if(['originator','closer','table'].includes(e.target.name))refreshSaleRates();else previewSale();});
document.querySelector('#sale-form').addEventListener('input',e=>{if(['amount','originRate','closerRate'].includes(e.target.name))previewSale();});
const saleRuleHelp=typeof document.querySelectorAll==='function'?[...document.querySelectorAll('#sale-form .hint')].at(-1):null;if(saleRuleHelp)saleRuleHelp.textContent='Cada taxa é aplicada integralmente. Se a mesma pessoa trouxe e fechou, as duas taxas são somadas. Parcelinha: cada participação usa 0,8% ÷ 12. O cálculo arredonda somente o valor final em centavos.';

function parseCredit(value){const raw=String(value).replace(/R\$/g,'').replace(/\s/g,'');if(!/^(?:\d+|\d{1,3}(?:\.\d{3})+)(?:,\d{0,2})?$/.test(raw))return NaN;const [whole,fraction='']=raw.replace(/\./g,'').split(',');return Number(whole)*100+Number(fraction.padEnd(2,'0'));}
function formatCredit(amount){return (amount/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});}
function maskCredit(input){const raw=input.value,start=input.selectionStart??raw.length,comma=raw.indexOf(','),fraction=comma>=0&&start>comma,digitsBefore=raw.slice(0,start).replace(/\D/g,'').length,amount=parseCredit(raw.replace(/\./g,'').replace(/(,\d{2})\d+$/, '$1'));if(!Number.isSafeInteger(amount)||amount>100000000000000)return;input.value=formatCredit(amount);let caret;if(fraction)caret=input.value.indexOf(',')+1+Math.min(2,start-comma-1);else{let count=0;caret=0;while(caret<input.value.indexOf(',')&&count<digitsBefore){if(/\d/.test(input.value[caret]))count++;caret++;}}input.setSelectionRange(caret,caret);}
